def is_prime(num: int) -> bool:
    def prime_tests(num: int) -> List[bool]:
        tests = []
        if num <= 1:
            tests.append(False)
        elif num == 2 or num == 3:
            tests.append(True)
        elif num % 2 == 0 or num % 3 == 0:
            tests.append(False)
        else:
            for i in range(5, int(num ** 0.5) + 1, 6):
                if num % i == 0 or num % (i + 2) == 0:
                    tests.append(False)
                else:
                    tests.append(True)
        return tests

    return all(prime_tests(num))
