def generate_numbers(n, rules):
    seen = set([n])
    queue = [n]
    count = 1

    while queue:
        current = queue.pop(0)
        for rule in rules:
            if str(rule[0]) in str(current):
                transformed = current.replace(str(rule[0]), str(rule[1]))
                if transformed not in seen:
                    seen.add(transformed)
                    queue.append(transformed)
                    count += 1

    return count
